NAME = 'ACV: A Conservative Version'
BOOK = 'I Corinthians'

CHAPTERS = {
    1: {
        1: 'Pavel, poklican apostol Jezusa Kristusa po volji Božji, in Sosten, brat,',
        2: 'cerkvi Božji, ki je v Korintu, posvečenim v Kristusu Jezusu, poklicanim svetim, z vsemi, ki kličejo ime Gospoda našega Jezusa Kristusa na vsakem mestu, svojem in našem:',
        3: 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa.',
        4: 'Zahvaljujem Boga svojega vsekdar za vas, za milost Božjo, dano vam v Kristusu Jezusu,',
        5: 'da ste v vsem obogateli v njem, v vsaki besedi in v vsakem spoznanju,',
        6: 'kakor se je pričevanje Kristusovo utrdilo med vami,',
        7: 'tako da ne primanjkuje nobenega daru milosti vam, ki pričakujete razodetja Gospoda našega Jezusa Kristusa;',
        8: 'ki vas tudi utrdi do konca, da bodete brez graje v dan Gospoda našega Jezusa Kristusa.',
        9: 'Zvest je Bog, po katerem ste poklicani v deleštvo Sinu njegovega, Jezusa Kristusa, Gospoda našega.',
        10: 'Prosim vas pa, bratje, v imenu Gospoda našega Jezusa Kristusa, da vsi eno govorite in ne bodi razdorov med vami, temuč bodite popolnoma složni v enem umu in eni misli.',
        11: 'Povedali so mi namreč za vas, bratje moji, Hlojini domači, da so prepiri med vami.',
        12: 'Menim pa to, da vsak vas govori: Jaz sem Pavlov, jaz pa Apolov, jaz pa Kefov, a jaz Kristusov.',
        13: 'Je li Kristus razdeljen? je li bil Pavel na križ razpet za vas, ali ste bili v ime Pavlovo krščeni?',
        14: 'Hvalim Boga, da nisem nikogar vas krstil razen Krispa in Gaja,',
        15: 'da kdo ne poreče, da ste bili krščeni v moje ime.',
        16: 'Krstil sem pa tudi Štefanovo družino; sicer ne vem, če sem še koga krstil.',
        17: 'Zakaj Kristus me ni poslal krščevat, temuč oznanjevat evangelij, ne v modrosti besede, da se ne uniči moč križa Kristusovega.',
        18: 'Kajti beseda o križu je tistim, ki gredo v pogubo, neumnost, nam pa, ki se zveličujemo, je moč Božja.',
        19: 'Kajti pisano je: „Pogubim modrost modrih in razumnost razumnih zavržem“.',
        20: 'Kje je modrijan? Kje pismouk? Kje preiskovalec tega sveta? Ni li Bog v neumnost preobrnil modrosti tega sveta?',
        21: 'Ker namreč svet v modrosti Božji ni spoznal Boga po svoji modrosti, je sklenil Bog po neumnosti oznanjevanja zveličati te, kateri verujejo.',
        22: 'Kajti i Judje zahtevajo znamenj, i Grki iščejo modrosti.',
        23: 'Mi pa oznanjujemo Kristusa na križ razpetega, Judom resda pohujšanje, poganom pa neumnost,',
        24: 'ali tistim, ki so poklicani, i Judom i Grkom, Kristusa, Božjo moč in Božjo modrost.',
        25: 'Ker ‚neumnost‘Božja je modrejša od ljudi in ‚slabost‘Božja močnejša od ljudi.',
        26: 'Kajti glejte poklic svoj, bratje, da ni poklicanih mnogo modrih po mesu, ne mnogo mogočnih, ne mnogo imenitnih;',
        27: 'marveč kar je neumnega na tem svetu, to si je Bog izbral, da osramoti modre, in kar je slabotnega na tem svetu, to si je Bog izbral, da osramoti, kar je mogočnega;',
        28: 'in kar je neimenitno na tem svetu in zaničevano, si je izbral Bog in to, česar ni, da uniči to, kar je:',
        29: 'da se ne hvali nobeno meso pred obličjem Božjim.',
        30: 'Iz njega pa ste vi v Kristusu Jezusu, ki nam je postal modrost od Boga, pa tudi pravičnost in posvečenje in odrešenje,',
        31: 'da, kakor je pisano, „kdor se hvali, v Gospodu naj se hvali“.',
    },
    2: {
        1: 'Tudi jaz, ko sem prišel k vam, bratje, nisem prišel z visokostjo besede ali modrosti oznanjevat vam pričevanja Božjega.',
        2: 'Odločil sem se namreč, da ne bom vedel kaj drugega med vami razen Jezusa Kristusa in tega na križ razpetega.',
        3: 'In bil sem pri vas v slabosti in v strahu in mnogem trepetu.',
        4: 'In govor moj in propovedovanje moje ni bilo v prepričevalnih besedah človeške modrosti, temuč v dokazovanju Duha in moči,',
        5: 'da bi vera vaša ne slonela na modrosti človeški, ampak na moči Božji.',
        6: 'Vendar pa modrost govorimo med popolnimi, a ne modrosti tega sveta niti poglavarjev tega sveta, kateri ginejo;',
        7: 'marveč govorimo modrost Božjo v skrivnosti, tisto skrito modrost, ki jo je naprej odločil Bog pred veki za našo slavo,',
        8: 'ki je ni nihče izmed poglavarjev tega sveta spoznal; ker ko bi jo bili spoznali, ne bi bili Gospoda slave razpeli na križ; temuč kakor je pisano:',
        9: '„Česar oko ni videlo in uho ni slišalo in kar v srce človeku ni prišlo, to je pripravil Bog tem, kateri ga ljubijo“.',
        10: 'Nam pa je to Bog razodel po Duhu svojem; kajti Duh vse preiskuje, tudi globočine Božje.',
        11: 'Kajti kdo ve izmed ljudi, kaj je v človeku, razen človekovega duha, ki je v njem? Tako tudi ne ve nihče, kaj je v Bogu, razen le Božji Duh.',
        12: 'Mi pa nismo prejeli duha tega sveta, ampak Duha, ki je iz Boga, da vemo, kaj nam je milostno daroval Bog;',
        13: 'to tudi govorimo, ne v besedah, ki jih uči človeška modrost, temuč v teh, ki jih uči Duh, in duhovne stvari skladamo z duhovnimi.',
        14: 'Telesni človek pa ne sprejema, kar je Duha Božjega, ker mu je neumnost in ne more tega umeti, ker se mora duhovno razsojati.',
        15: 'Duhovni človek pa razsoja vse; a njega samega ne razsoja nihče.',
        16: 'Kajti „kdo je spoznal um Gospodov, da bi ga poučil?“Mi pa imamo um Kristusov.',
    },
    3: {
        1: 'Tudi jaz, bratje, nisem mogel govoriti vam kakor duhovnim, temuč kakor mesenim, kakor nedoraslim v Kristusu.',
        2: 'Mleka sem vam dal piti, ne jedi, kajti niste je še zmogli; pa tudi še sedaj je ne zmorete,',
        3: 'ker ste še meseni. Kajti kjer je med vami zavist in prepir, niste li meseni in ne postopate li po človeški?',
        4: 'Če namreč kdo pravi: ‚Jaz sem Pavlov‘, a drugi: ‚Jaz sem Apolov‘, niste li meseni ljudje?',
        5: 'Kaj je torej Apolo? in kaj je Pavel? Služabnika sta, po katerih ste vero sprejeli, in to, kakor je Gospod vsakteremu dal:',
        6: 'jaz sem sadil, Apolo je zalil, ali Bog je dal, da je zraslo.',
        7: 'Tako ni ne tisti kaj, kateri sadi, ne, kateri zaliva, temuč ki daje rasti, Bog.',
        8: 'Ta pa, ki sadi in ki zaliva, sta eno; vsak pa prejme svoje plačilo po lastnem trudu.',
        9: 'Božji namreč smo sodelavci; Božja njiva, Božje poslopje ste vi.',
        10: 'Po milosti Božji, ki mi je dana, sem položil kakor modri zidar temelj, a drug nanj zida; ali vsak naj gleda, kako nanj zida.',
        11: 'Kajti drugega temelja ne more nihče položiti razen tega, ki je položen, ki je Jezus Kristus.',
        12: 'Če pa kdo zida na ta temelj zlato, srebro, drago kamenje, drva, seno, strn:',
        13: 'vsakega delo postane očitno; kajti dan ga razodene, ker se v ognju odkrije, in ogenj preizkusi delo vsakega, kakšno je.',
        14: 'Če ostane komu delo, katero je postavil na njem, prejme plačilo;',
        15: 'če komu delo zgori, prejme škodo, sam pa bo zveličan, ali tako, kakor po ognju.',
        16: 'Ne veste, da ste tempelj Božji in da Duh Božji prebiva v vas?',
        17: 'Če kdo pokvari tempelj Božji, tega pogubi Bog; zakaj tempelj Božji je svet, kateri ste vi.',
        18: 'Nihče naj sebe ne slepi! Če kdo misli, da je moder med vami na tem svetu, naj postane neumen, da postane moder.',
        19: 'Kajti modrost tega sveta je neumnost pri Bogu. Pisano je namreč: „On zasačuje modre v njih lastni zvijači“;',
        20: 'in zopet: „Gospod pozna misli modrih, da so prazne“.',
        21: 'Tako naj se nihče ne hvali z ljudmi. Kajti vse je vaše,',
        22: 'bodi si Pavel ali Apolo ali Kefa, bodisi svet ali življenje ali smrt, bodisi sedanje ali bodoče: vse je vaše,',
        23: 'vi pa ste Kristusovi, a Kristus Božji.',
    },
    4: {
        1: 'Tako naj o nas misli človek, kakor da smo služabniki Kristusovi oskrbniki skrivnosti Božjih.',
        2: 'Seveda se tu zahteva od oskrbnikov, da se vsak izkaže zvestega.',
        3: 'Meni je pa to najmanjše, da me sodite vi ali človeški sodni dan; ali tudi sam sebe ne sodim;',
        4: 'kajti ničesar nimam sam sebi očitati, ali to me ne opravičuje; sodnik pa mi je Gospod.',
        5: 'Tako ne sodite ničesar pred časom, dokler ne pride Gospod, ki razsvetli, kar je skritega v temi, in odkrije misli src; in tedaj se hvala zgodi vsakemu od Boga.',
        6: 'To sem pa, bratje, obrnil nase in na Apola zavoljo vas, da se od naju naučite ne više meriti, nego je pisano, da se nihče ne napihuje, vnet za enega zoper drugega.',
        7: 'Ker kdo je, ki te odlikuje? kaj pa imaš, česar nisi prejel? Če si pa tudi prejel, kaj se hvališ, kakor da nisi prejel?',
        8: 'Že ste nasičeni, že ste obogateli, brez nas ste zakraljevali; in želim, da bi bili res zakraljevali, da bi mogli tudi mi z vami kraljevati!',
        9: 'Mislim namreč, da je Bog nas apostole poslednje postavil kakor tiste, ki so odločeni za smrt, ker smo postali gledišče svetu, i angelom i ljudem.',
        10: 'Mi smo neumni za voljo Kristusa, a vi razumni v Kristusu, mi slabi, a vi močni, vi slavni, a mi brez časti.',
        11: 'Prav dosore trpimo lakoto in žejo, in goli smo in bijejo nas za ušesa, in nimamo stalnega mesta',
        12: 'in trudimo se, delajoč z lastnimi rokami; ko nas zmerjajo, blagoslavljamo; ko nas preganjajo, voljno trpimo;',
        13: 'ko nas preklinjajo, molimo; kakor smeti sveta smo postali, izvržek vseh, prav do sedaj.',
        14: 'Ne pišem tega, da bi vas sramotil, marveč svarim vas kakor svoje ljubljene otroke.',
        15: 'Zakaj čeprav bi imeli deset tisoč učiteljev v Kristusu, vendar nimate mnogo očetov, ker v Kristusu Jezusu po evangeliju sem vas jaz rodil.',
        16: 'Prosim vas torej, bodite moji posnemalci.',
        17: 'Zato sem vam poslal Timoteja, ki je dete moje ljubljeno in verno v Gospodu, ki vas opomni mojih poti, ki so v Kristusu, kakor učim povsod v vsaki cerkvi.',
        18: 'Nekateri pa so se napihnili, češ, da ne pridem k vam.',
        19: 'Ali pridem kmalu k vam, če Gospod hoče, in spoznam ne besed napihnjencev, ampak njih moč.',
        20: 'Kajti ni v besedah kraljestvo Božje, temuč v moči.',
        21: 'Kaj hočete? da naj pridem k vam s šibo, ali z ljubeznijo in v duhu krotkosti?',
    },
    5: {
        1: 'Sploh se sliši da je nečistost med vami, in to taka nečistost, kakršne še med pogani ni, da ima nekdo svojega očeta ženo.',
        2: 'In vi ste napihnjeni in niste bili rajši žalostni, da bi se odpravil izmed vas tisti, ki je storil tako delo?',
        3: 'Kajti jaz, sicer nenavzočen s telesom, a navzočen z duhom, sem že sodil, kakor da sem navzočen, tistega, ki je to tako storil,',
        4: 'da bodi v imenu Gospoda našega Jezusa, kadar se zberete vi in moj duh, z močjo Gospoda našega Jezusa,',
        5: 'izročen satanu na pogubo mesa, da se duh zveliča na dan Gospoda Jezusa.',
        6: 'Ni dobra hvala vaša. Ne veste li, da malo kvasu skisa vse testo?',
        7: 'Postrgajte torej stari kvas, da bodete novo testo, kakor ste opresni. Kajti tudi naše velikonočno jagnje je bilo darovano, Kristus:',
        8: 'zato praznujmo ne v starem kvasu, tudi ne v kvasu hudobnosti in malopridnosti, temuč v presnini čistote in resnice.',
        9: 'Pisal sem vam v listu, da se ne mešajte z nečistniki,',
        10: 'ne sploh z nečistniki tega sveta, ali z lakomniki, ali roparji, ali malikovci, ker bi sicer morali oditi s tega sveta;',
        11: 'ampak pisal sem vam, meneč, da se ne mešate, če je ta, ki se brat imenuje, nečistnik, ali lakomnik, ali malikovalec, ali opravljivec, ali pijanec, ali ropar: s takim da še ne jeste.',
        12: 'Kajti kaj je meni mari, da sodim tiste, ki so zunaj? Ne sodite vi tistih, ki so notri?',
        13: 'Kateri so pa zunaj, tiste bo sodil Bog. Odpravite hudobnika izmed sebe!',
    },
    6: {
        1: 'Drzne li se kdo izmed vas, ko ima tožbo zoper drugega, pravdati se pred nepravičnimi in ne pred svetimi?',
        2: 'Ali pa ne veste, da bodo sveti sodili svet? In če bo po vas sojen svet, kaj ste nevredni, da sodite najmanjše stvari?',
        3: 'Ne veste, da bomo angele sodili? kaj še stvari, ki se tičejo tega življenja!',
        4: 'Kadar imate torej sodbe, ki se tičejo tega življenja, ali postavljate za sodnike tiste, ki niso nič cenjeni v cerkvi?',
        5: 'Na sramoto vam govorim. Tako torej ni modrega med vami ne enega, ki bi mogel razsoditi med brati svojimi?',
        6: 'Ampak brat se z bratom pravda in to pred neverniki!',
        7: 'Že to je res celo slabo pri vas, da imate sodbe med seboj. Zakaj si ne daste rajši krivice delati? zakaj se rajši ne daste oškodovati?',
        8: 'Temuč vi delate krivico in napravljate škodo, in to bratom.',
        9: 'Ali pa ne veste, da krivičniki ne podedujejo kraljestva Božjega? Ne motite se: ne nečistniki, ne malikovalci, ne prešeštniki, ne mehkuži, ne moželežniki,',
        10: 'ne tatje, ne lakomniki, ne pijanci, ne obrekovalci, ne roparji ne podedujejo kraljestva Božjega.',
        11: 'In taki ste bili nekateri; ali umili ste se, ali posvečeni ste bili, ali opravičeni ste bili v imenu Gospoda Jezusa Kristusa in v Duhu Boga našega.',
        12: 'Vse mi je dopuščeno, ali ni vse koristno. Vse mi je dopuščeno, ali jaz se ne dam ničemur obvladati.',
        13: 'Jedi so za trebuh, a trebuh za jedi, ali Bog bo onega in te pokončal. Telo pa ni za nečistost, nego za Gospoda in Gospod za telo.',
        14: 'Bog je pa Gospoda obudil, pa tudi nas obudi s svojo močjo.',
        15: 'Ne veste, da so vaša telesa udje Kristusovi? Vzamem naj torej ude Kristusove in jih storim ude nečistnice? Nikakor ne.',
        16: 'Ali pa ne veste, kdor se z nečistnico druži, da je eno telo ž njo? Kajti „ta dva“, je dejal, „bodeta eno meso“.',
        17: 'A kdor se z Gospodom druži, eden je duh ž njim.',
        18: 'Bežite od nečistosti! Vsak greh, katerega koli stori človek, je zunaj telesa; kdor pa nečistuje, greši na lastnem telesu.',
        19: 'Ali pa ne veste, da je vaše telo tempelj svetega Duha, ki prebiva v vas, ki ga imate od Boga, in niste sami svoji?',
        20: 'Kajti kupljeni ste za drago ceno. Poslavite torej Boga v telesu svojem!',
    },
    7: {
        1: 'Zastran tega pa, kar ste mi pisali: Dobro je človeku, žene se ne dotikati.',
        2: 'A da ne bo nečistosti, zato imej vsak svojo ženo in vsaka imej svojega moža.',
        3: 'Ženi mož izpolnjuj dolžnost, takisto tudi žena možu.',
        4: 'Žena nad svojim telesom nima oblasti, temuč mož; takisto tudi nad svojim telesom nima oblasti mož, temuč žena.',
        5: 'Ne odtegujta se drug drugemu, razen z dogovorom za čas, da bi bolj utegnila moliti in bi zopet skupaj bivala, da vaju ne izkuša satan za voljo nezdržljivosti vajine.',
        6: 'To pa govorim kot dopuščenje, ne kot zapoved.',
        7: 'Hotel bi pa, da bi bili vsi ljudje, kakor sem jaz; toda vsak ima svoj dar milosti od Boga, ta tako, a drugi tako.',
        8: 'Pravim pa neoženjenim in vdovam: Dobro jim je, če ostanejo, kakor jaz.',
        9: 'Če se pa ne morejo zdržati, naj stopijo v zakon, ker je bolje stopiti v zakon nego pa goreti.',
        10: 'Zakonskim pa naročam ne jaz, ampak Gospod, naj se ne loči žena od moža',
        11: '(če pa se vendar loči, naj ostane brez moža ali pa naj se spravi z možem), in mož naj ne odpušča žene.',
        12: 'Drugim pa pravim jaz, ne Gospod: Če ima kateri brat ženo nevernico in ona privoljuje prebivati ž njim, naj se ne loči ž njo.',
        13: 'In žena, če ima moža nevernika in on privoljuje prebivati ž njo, naj se ne loči ž njim.',
        14: 'Posvečen je namreč mož nevernik po ženi in žena nevernica je posvečena po bratu; ker bi sicer bili nečisti vaši otroci, sedaj pa so sveti.',
        15: 'Če se pa hoče nevernik ločiti, naj se loči. Ni suženjski vezan brat ali sestra v takih slučajih; na mir pa nas je poklical Bog.',
        16: 'Ker kaj veš, žena, če moža zveličaš? ali kaj veš, mož, če ženo zveličaš?',
        17: 'Le kakor je vsakemu podelil Gospod, kakor je vsakega poklical Bog, tako naj ravna. In tako velevam po vseh cerkvah.',
        18: 'Obrezan li je kdo poklican? Naj se ne dela neobrezanega. V neobrezi je kdo poklican? Naj se ne obrezuje.',
        19: 'Obreza ni nič in neobreza ni nič, ampak izpolnjevanje Božjih zapovedi.',
        20: 'Vsak naj ostane v tem poklicu, v katerem je bil poklican.',
        21: 'Suženj si bil poklican? Ne maraj; ali če moreš postati svoboden, poprimi se rajši svobode.',
        22: 'Kajti kdor je v Gospodu poklican suženj, je svobodnik Gospodov, tako tudi kdor je poklican svobodnik, je suženj Kristusov.',
        23: 'Za drago ceno ste kupljeni; ne postanite sužnji ljudem.',
        24: 'Vsakdo, bratje, naj ostane pri Bogu v tem, v čemer je bil poklican.',
        25: 'Zastran devic pa nimam Gospodove zapovedi, ali dajem svet, kakor kateri sem prejel milost od Gospoda, da bi bil zvest.',
        26: 'Menim torej, da je to dobro spričo sedanje nuje, namreč da je dobro biti človeku tako, kakor je.',
        27: 'Si li privezan na ženo, ne išči razveze. Si li prost žene, ne išči žene.',
        28: 'A če se tudi oženiš, se ne pregrešiš; tudi devica, če se omoži, se ne pregreši; toda telesne nadloge bodo imeli taki; jaz bi vam pa rad prizanesel.',
        29: 'To pa pravim, bratje: čas je prikrajšan, da bodo odslej tudi tisti, ki imajo žene, kakor bi jih ne imeli;',
        30: 'in kateri jokajo, kakor bi ne jokali; in kateri se vesele, kakor bi se ne veselili; in kateri kupujejo, kakor bi v lasti ne imeli;',
        31: 'in kateri uživajo ta svet, kakor bi ga ne uživali; kajti prehaja obraz tega sveta.',
        32: 'Hotel bi pa da ste brez skrbi. Kdor je neoženjen, skrbi za to, kar je Gospodovega, kako bi bil Gospodu po volji.',
        33: 'Kdor se je pa oženil, skrbi za to, kar je na svetu, kako bi ženi ugajal. Razloček je tudi med ženo in devico.',
        34: 'Katera je brez moža, skrbi za to, kar je Gospodovega, da bi bila sveta s telesom in z duhom. Omožena pa skrbi za to, kar je na svetu, kako bo ugajala možu.',
        35: 'To pa govorim vam samim na korist, ne da vržem zanko na vas, temuč da spodobno ravnate in stanovitno služite Gospodu brez ovire.',
        36: 'A če kdo meni, da spravi v sramoto devico svojo, ko bi bila v prezreli dobi, in potreba tako zahteva, kar hoče, naj dela, ne greši; naj se možé!',
        37: 'Kdor pa stoji trden v srcu svojem in nima potrebe, a ima oblast nad lastno voljo, in je tako odločil v srcu svojem, da obvaruje svojo devico, stori dobro.',
        38: 'Tako kdor moži devico svojo, dela tudi dobro, a kdor je ne omoži, stori bolje.',
        39: 'Žena je vezana, dokler živi njen mož; ako ji pa mož umre, je prosta, da se moži, s komer hoče, samo v Gospodu.',
        40: 'Ali srečnejša je po mojem mnenju, če ostane tako; mislim pa, da imam tudi jaz Duha Božjega.',
    },
    8: {
        1: 'Zastran maliških žrtev pa vemo, da imamo vsi znanje. Znanje napihuje, a ljubezen pospešuje napredek.',
        2: 'Če kdo misli, da kaj pozna, ni še spoznal, kakor je treba spoznati.',
        3: 'Če pa kdo ljubi Boga, ta je spoznan od njega.',
        4: 'Zastran uživanja maliških žrtev torej vemo, da malik ni nič na svetu in da ni drugega Boga razen enega.',
        5: 'Kajti čeprav so, kateri se imenujejo bogovi, bodisi na nebu, bodisi na zemlji (kakor je bogov mnogo in gospodov mnogo),',
        6: 'ali za nas je eden Bog, Oče, iz katerega je vse in mi za njega; in eden Gospod, Jezus Kristus, po katerem je vse in mi po njem.',
        7: 'Ali ni v vseh tega spoznanja; kajti nekateri, doslej si v svesti, da je malik kaj, jedo mališke žrtve kot take, in njih vest, ker je slabotna, se skruni.',
        8: 'Jed pa nas ne dela prijetnih Bogu; kajti če ne jemo, nismo nič manjši, niti odličnejši, če jemo.',
        9: 'Glejte pa, da ne postane kako ta vaša svobodnost v spotiko slabotnim.',
        10: 'Ako namreč kdo ugleda tebe, ki imaš spoznanje, sedečega za mizo v svetišču malikov, ali se ne bo njegova vest, ker je slaboten, izpodbujala, da tudi jé mališke žrtve?',
        11: 'Kajti po tvojem spoznanju se ta slabotni spravlja v pogubo, in to brat, ki je zanj umrl Kristus.',
        12: 'Tako pa, grešeč zoper brate in bijoč njih slabotno vest, grešite zoper Kristusa.',
        13: 'Zato če jed pohujšuje brata mojega, ne bom jedel mesa nikdar ne, da ne pohujšam brata svojega.',
    },
    9: {
        1: 'Ali nisem svoboden? nisem li apostol? nisem li videl Jezusa, Gospoda našega? niste li vi moje delo v Gospodu?',
        2: 'Če drugim nisem apostol, sem pa vsaj vam; kajti pečat mojega apostolstva ste vi v Gospodu.',
        3: 'Moj zagovor tem, ki me sodijo, je ta:',
        4: 'Nimamo li pravice, da jemo in pijemo?',
        5: 'Nimamo li pravice, da vodimo sestro kot ženo s seboj, kakor tudi drugi apostoli in bratje Gospodovi in Kefa?',
        6: 'Ali samo jaz in Barnaba nimava pravice, da nehava delati?',
        7: 'Kdo služi kdaj za vojnika na svoje stroške? kdo sadi vinograd, pa ne jé njegovega sadu? Ali kdo pase čredo, pa ne jé mleka od črede?',
        8: 'Govorim li to po človeško? ali ne govori tega tudi postava?',
        9: 'Kajti v Mojzesovi postavi je pisano: „Ne zaveži gobca volu, ko vrši žito“. Skrbi li Bog za vole?',
        10: 'Ali pa pravi to vsekakor za nas? Res, za voljo nas je to pisano, ker kdor orje, mora z upanjem orati, in kdor mlati, mlatiti z upanjem, da bo imel svoj delež.',
        11: 'Če smo vam mi duhovno posejali, je li kaj velikega, ako bomo mi vaše meseno želi?',
        12: 'Če so drugi deležni te pravice pri vas, čemu ne tem bolj mi? Ali nismo se poslužili te pravice, marveč prenašamo vse, da ne provzročimo kake ovire evangeliju Kristusovemu.',
        13: 'Ne veste li, da ti, kateri opravljajo sveto službo, jedo od templja, in kateri služijo oltarju, imajo delež z oltarjem?',
        14: 'Tako je naredil tudi Gospod, da naj ti, kateri oznanjujejo evangelij, žive od evangelija.',
        15: 'Jaz pa se nisem poslužil ničesar tega. Ne pišem pa tega, da bi se tako godilo z menoj; kajti rajši umrem, nego da mi kdo uniči mojo hvalo.',
        16: 'Kajti če oznanjam evangelij, nimam nič hvale, ker to mi je neizogibna dolžnost; da, gorje mi, če evangelija ne oznanjam!',
        17: 'Če namreč delam to iz dobre volje, imam plačilo, če pa po sili, mi je poverjeno oskrbništvo.',
        18: 'Kaj je torej moje plačilo? Da oznanjujoč evangelij prinesem brez stroškov evangelij, tako da ne upotrebim pravice svoje v evangeliju.',
        19: 'Kajti dasi sem bil svoboden od vseh, sem se storil sužnja vsem, da bi jih tem več pridobil.',
        20: 'In Judom sem postal kakor Jud, da bi Jude pridobil; tistim, ki so pod postavo, kakor bi bil pod postavo, čeprav sam nisem pod postavo, da bi pridobil te, kateri so pod postavo;',
        21: 'tistim pa, ki so brez postave, kakor bi bil brez postave, dasi nisem brez postave Bogu, temuč v postavi Kristusu, da bi pridobil tiste, ki so brez postave;',
        22: 'slabotnim sem postal slabič, da bi pridobil slabiče: vsem sem postal vse, da bi jih vsekakor nekaj zveličal.',
        23: 'Vse pa delam zavoljo evangelija, da bi prejel delež ž njim.',
        24: 'Ne veste li, da tisti, ki teko na tekališču, vsi sicer teko, a eden prejme darilo? Tako tecite, da ga dosežete!',
        25: 'Vsak pa, ki se tam bori, se zdržuje vsega: oni seveda, da dobe strohljiv venec, mi pa nestrohljivega.',
        26: 'Jaz torej tečem tako, ne kakor na negotovo; tako se borim, ne kakor bi po zraku mahal,',
        27: 'temuč tarem svoje telo in ga usnužnujem, da ne bi kako, ko sem drugim oznanjeval, sam bil zavrgljiv.',
    },
    10: {
        1: 'Nočem namreč, bratje, da bi ne vedeli, da so bili naši očetje vsi pod oblakom in da so prešli vsi skozi morje,',
        2: 'in so bili vsi v Mojzesa krščeni v oblaku in morju',
        3: 'in so vsi jedli isto duhovno jed',
        4: 'in vsi pili isto duhovno pijačo; pili so namreč iz duhovne skale, ki jih je spremljala, a ta skala je bila Kristus.',
        5: 'Toda večina njih ni bila po volji Bogu; zakaj pobiti so bili v puščavi.',
        6: 'To pa so postali zgledi za nas, da bi ne želeli hudega, kakor so tudi oni poželeli.',
        7: 'Tudi ne bodite malikovalci kot nekateri njih, kakor je pisano: „Sedlo je ljudstvo jest in pit in vstalo igrat“.',
        8: 'Tudi ne nečistujmo, kakor so nekateri izmed njih nečistovali, in padlo jih je v enem dnevu triindvajset tisoč.',
        9: 'Tudi ne izkušajmo Gospoda, kakor so ga nekateri izmed njih izkušali in so poginili od kač.',
        10: 'Tudi ne mrmrajte, kakor so nekateri izmed njih mrmrali in so poginili od pogubnika.',
        11: 'To vse pa se jim je zgodilo kot zgledi, a napisalo se je za svarilo nam, na katere so prišli konci vekov.',
        12: 'Kdor torej misli, da stoji, naj gleda, da ne pade.',
        13: 'Ni vas nobena izkušnjava zadela razen take, ki jo more človek prenesti; zvest pa je Bog, ki vam ne da biti izkušanim nad vašo moč, temuč stori z izkušnjavo tudi izhod iz nje, da jo morete prenesti.',
        14: 'Zatorej, ljubljeni moji, bežite od malikovalstva!',
        15: 'Kakor pametnim govorim; razsodite vi, kar pravim.',
        16: 'Kelih blagoslova, ki ga blagoslavljamo, ni li deležnost krvi Kristusove? Kruh, ki ga lomimo, ni deležnost telesa Kristusovega?',
        17: 'Ker je en kruh, smo eno telo mnogi, kajti vsi smo deležni tega enega kruha.',
        18: 'Glejte Izraela po mesu: niso li, kateri jedo žrtve, deležniki oltarja?',
        19: 'Kaj torej pravim? Da je mališka žrtva kaj? ali da je malik kaj?',
        20: 'Nikakor, temuč kar žrtvujejo pogani, da žrtvujejo zlim duhovom in ne Bogu. Nočem pa, da bodete vi deležniki zlih duhov.',
        21: 'Ne morete piti keliha Gospodovega in keliha zlih duhov, ne morete biti deležni mize Gospodove in mize zlih duhov.',
        22: 'Ali pa hočemo dražiti Gospoda? smo li močnejši od njega?',
        23: 'Vse je dopuščeno, ali ni vse koristno; vse je dopuščeno, ali vse ne pospešuje napredka.',
        24: 'Nihče naj ne išče svojega, temuč vsak dobro drugega.',
        25: 'Vse, kar prodajajo v mesnici, jejte, nič ne povprašujoč zavoljo vesti.',
        26: 'Kajti „Gospodova je zemlja in kar jo napolnjuje“.',
        27: 'Če pa vas povabi kdo nevernikov in hočete iti, jejte vse, kar stavijo pred vas, nič povprašujoč zavoljo vesti.',
        28: 'Ako pa vam kdo poreče: ‚To je mališka žrtva‘, ne jejte zavoljo tistega, ki je to oznanil, in zavoljo vesti;',
        29: 'ne pravim pa zavoljo vesti tvoje, temuč onega drugega. Kajti čemu naj mojo svobodo sodi tuja vest?',
        30: 'Če jaz uživam kaj s hvalo Bogu, zakaj naj bi bil preklinjan ob tem, za kar se zahvaljujem?',
        31: 'Če torej jeste ali pijete ali karkoli delate, vse delajte Bogu na slavo.',
        32: 'Bodite brez spotike Judom in Grkom in cerkvi Božji,',
        33: 'kakor delam tudi jaz v vseh rečeh vsem pogodu, ne iščoč, kar je koristno meni, temuč kar je v korist mnogim, da se zveličajo.',
    },
    11: {
        1: 'Posnemalci moji bodite, kakor sem tudi jaz Kristusov.',
        2: 'Hvalim vas pa, bratje, da se v vsem mene spominjate in se držite zapovedi, kakor sem vam jih izročil.',
        3: 'Hočem pa, da veste, da je vsakemu možu glava Kristus, a glava ženi mož, glava pa Kristusu Bog.',
        4: 'Vsak mož, ki moli ali prorokuje s pokrito glavo, sramoti svojo glavo.',
        5: 'Vsaka žena pa, ki moli ali prorokuje razoglava, sramoti svojo glavo; zakaj to je toliko, kakor bi bila ostrižena.',
        6: 'Kajti če se ne pokriva žena, naj se tudi striže; če je pa sramota za ženo striči se ali briti, naj se pokriva.',
        7: 'Možu namreč ni treba pokrivati glave, ker je podoba in slava Božja; a žena je slava moževa.',
        8: 'Zakaj mož ni od žene, temuč žena od moža;',
        9: 'saj tudi ni ustvarjen mož za voljo žene, temuč žena za voljo moža.',
        10: 'Zato mora imeti žena znamenje moževe oblasti na glavi za voljo angelov.',
        11: 'Sicer pa ni ne mož brez žene, ne žena brez moža v Gospodu.',
        12: 'Kajti kakor je žena od moža, tako je tudi mož po ženi, a vse je iz Boga.',
        13: 'Sami pri sebi presodite, je li spodobno za ženo, da razoglava moli k Bogu.',
        14: 'Ali vas ne uči sama narava, da je možu v sramoto, če si goji dolge lase?',
        15: 'a ženi, če si goji dolge lase, da je čast? ker so ji lasje dani za pokrivalo.',
        16: 'Če se pa komu zdi, da se mora prepirati: mi te navade nimamo, tudi cerkve Božje ne.',
        17: 'Ko pa to naročam, ne hvalim, da se ne na boljše, temuč na hujše shajate.',
        18: 'Kajti prvič, kadar se shajate v zboru, slišim da so razpori med vami, in nekoliko verjamem to.',
        19: 'Zakaj potrebno je, da so tudi krivoverstva med vami, da se pokažejo med vami, kateri so v veri izkušeni.',
        20: 'Ko se torej shajate na en kraj, to ni Gospodovo večerjo jesti;',
        21: 'kajti ob vaši skupni jedi užije vsak svojo večerjo poprej, in tako je eden lačen, a drugi se opija.',
        22: 'Nimate li mar hiš, da v njih jeste in pijete? Ali pa zaničujete zbor Božji in sramotite tiste, ki nimajo ničesar? Kaj naj vam rečem? naj vas hvalim? V tem ne hvalim.',
        23: 'Zakaj jaz sem prejel od Gospoda, kar sem tudi vam izročil: da je Gospod Jezus tisto noč, v kateri je bil izdan, vzel kruh',
        24: 'in, zahvalivši se, ga je prelomil in rekel: Vzemite, jejte: to je moje telo, ki je za vas; to delajte v moj spomin.',
        25: 'Tako tudi kelih po večerji, rekoč: Ta kelih je nova zaveza v moji krvi; to delajte, kolikorkolikrat pijete, v moj spomin.',
        26: 'Kajti kolikorkolikrat jeste ta kruh in pijete ta kelih, oznanjujete smrt Gospodovo, dokler ne pride.',
        27: 'Zatorej kdor jé ta kruh in pije kelih Gospodov nevredno, kriv bo telesa in krvi Gospodove.',
        28: 'Ali človek naj izkuša sam sebe in tako naj jé od kruha in pije od keliha;',
        29: 'zakaj kdor jé in pije nevredno, jé in pije sebi sodbo, ker ne razločuje telesa Gospodovega.',
        30: 'Zato so mnogi med vami slabi in bolni in dosti jih spi.',
        31: 'Ko bi pa mi sami sebe razsojali, ne bi bili sojeni.',
        32: 'Ko smo pa sojeni, nas strahuje Gospod, da ne bi bili s svetom obsojeni.',
        33: 'Tako, bratje moji, ko se shajate k jedi, čakajte drug drugega.',
        34: 'Je li pa kdo lačen, jej doma, da bi se ne shajali na obsojenje. Drugo pa uredim, kadar pridem.',
    },
    12: {
        1: 'A zastran duhovnih darov nočem, bratje, da bi bili nepoučeni.',
        2: 'Veste, da ste zahajali, ko ste bili pogani, k nemim malikom, kamorkoli so vas vodili.',
        3: 'Zato vam dajem na znanje, da nihče v Duhu Božjem govoreč, ne reče: ‚Proklet bodi Jezus‘, in nihče ne more reči: ‚Jezus je Gospod‘, razen v svetem Duhu.',
        4: 'So pa razločki v darovih, ali eden je Duh,',
        5: 'in so razločki v službah, ali eden je Gospod,',
        6: 'in so razločki v delovanju, ali eden je Bog, ki dela vse v vseh.',
        7: 'A vsakemu se daje razodevanje Duha v občno korist.',
        8: 'Enemu se namreč po Duhu daje beseda modrosti, a drugemu beseda znanja po istem Duhu,',
        9: 'drugemu pa vera v istem Duhu, a drugemu dar ozdravljati v istem Duhu,',
        10: 'a drugemu dela čudežnih moči, drugemu pa proroštvo, a drugemu razločevanje duhov, drugemu pa raznovrstnost jezikov, a drugemu razkladanje jezikov.',
        11: 'A vse to dela isti edini Duh, podeljujoč vsakemu posebe, kakor hoče.',
        12: 'Kajti kakor je telo eno in ima mnogo duhov, a vsi udje enega telesa, čeprav jih je mnogo, so eno telo: tako tudi Kristus.',
        13: 'Z enim Duhom namreč smo mi vsi krščeni v eno telo, bodisi Judje ali Grki, bodisi sužnji ali svobodniki, in vsi smo napojeni enega Duha.',
        14: 'Saj tudi telo ni eden ud, temuč mnogi.',
        15: 'Ako reče noga: ‚Ker nisem roka, nisem od telesa‘, ali zato ni od telesa?',
        16: 'In ako reče uho: ‚Ker nisem oko, nisem od telesa‘, ni li zato od telesa?',
        17: 'Ko bi bilo celo telo oko, kje bi bil sluh? ko bi bilo celo sluh, kje bi bil voh?',
        18: 'Tako pa je Bog postavil ude, slehernega izmed njih po telesu, kakor je hotel.',
        19: 'Ko bi bili pa vsi eden ud, kje bi bilo telo?',
        20: 'Tako so pa sicer mnogi udje, a telo eno.',
        21: 'Nikar ne more oko reči roki: ‚Ni te mi treba‘, ali zopet glava nogama: ‚Ni mi vaju treba‘.',
        22: 'Marveč tisti udje telesa, ki se zde slabejši, so tem bolj potrebni;',
        23: 'in kateri se nam zde manj častni na telesu, okoli teh stavimo obilnejšo čast, in naši nespodobni dobivajo tem obilnejšo spodobnost;',
        24: 'našim spodobnim pa tega ni treba. Ali Bog je zložil telo, davši pomanjkljivemu večjo čast,',
        25: 'da bi ne bilo razpora v telesu, ampak da bi udje enako skrbeli drug za drugega.',
        26: 'In če trpi eden ud, ž njim trpe vsi udje; a če je en ud v slavi, se vesele ž njim vsi udje.',
        27: 'Vi pa ste telo Kristusovo in vsakteri zase je ud celote.',
        28: 'In nekatere si je postavil Bog v cerkvi prvič za apostole, drugič za proroke, tretjič za učitelje, potem je dal čudežne moči, potem darove ozdravljanja, zmožnost pomagati, vladati, raznovrstnost jezikov.',
        29: 'Ali so vsi apostoli? so li vsi preroki? so li vsi učitelji? imajo li vsi one moči?',
        30: 'imajo li vsi darove ozdravljanja? ali vsi govore jezike? ali vsi razkladajo?',
        31: 'Hrepenite pa po boljših darovih! In še boljšo pot vam kažem.',
    },
    13: {
        1: 'Ko bi govoril človeške jezike in angelske, a ljubezni ne bi imel, bi bil brneča med in zvenčeče cimbale.',
        2: 'In ko bi imel proroštvo in bi vedel vse skrivnosti in imel vse spoznanje, in ko bi imel vso vero, tako da bi gore prestavljal, a ljubezni ne bi imel, nič nisem.',
        3: 'In ko bi porazdal v živež ubogim vse, kar imam, in ko bi dal svoje telo, da zgorim, a ljubezni ne bi imel, nič mi ne koristi.',
        4: 'Ljubezen je potrpežljiva, dobrotljiva; ljubezen ni nevoščljiva, ljubezen se ne hvali, se ne napihuje,',
        5: 'ne vede se nespodobno, ne išče svojega, se ne da razdražiti, ne misli hudega,',
        6: 'ne veseli se krivice, a veseli se resnice;',
        7: 'vse pokriva, vse veruje, vse upa, vse prenaša.',
        8: 'Ljubezen nikoli ne mine; če pa so darovi proroštva, ponehajo, ali jeziki, umolknejo, ali spoznanje, preide.',
        9: 'Le po nekoliko namreč spoznavamo in le po nekoliko prorokujemo;',
        10: 'kadar pa pride, kar je popolno, tedaj premine ta nepopolnost.',
        11: 'Ko sem bil otrok, sem govoril kakor otrok, mislil kakor otrok, razsojal kakor otrok; odkar sem pa mož, sem opustil, kar je otročjega.',
        12: 'Kajti sedaj vidimo še skozi zrcalo, kakor v uganki, takrat pa bomo z licem v lice; sedaj spoznavam le nekoliko, takrat pa spoznam popolnoma, kakor sem bil tudi jaz spoznan.',
        13: 'Sedaj pa ostane vera, upanje, ljubezen, to troje; največja od njih pa je ljubezen.',
    },
    14: {
        1: 'Prizadevajte si za ljubezen, hrepenite pa tudi po duhovnih darovih, a najbolj, da prorokujete.',
        2: 'Kajti kdor govori v tujem jeziku, ne govori ljudem, ampak Bogu; kajti nihče ga ne razume, v duhu pa govori skrivnosti.',
        3: 'A kdor prorokuje, govori ljudem, da jim služi v napredovanje in jih tolaži in opominja:',
        4: 'Kdor govori v jeziku, streže sebi v napredek, kdor pa prorokuje, pospešuje napredek cerkve.',
        5: 'Hotel bi pa, da vsi govorite jezike, a veliko bolj, da prorokujete. Večji je, kdor prorokuje, nego kdor govori jezike, razen če bi razkladal, da bi cerkev prejela, kar ji služi v napredek.',
        6: 'Tako pa, bratje, če pridem k vam, jezike govoreč, kaj vam bom koristil, ko vam ne govorim ali v razodetju, ali v spoznanju, ali v proroštvu, ali v nauku?',
        7: 'Brezdušna godala, bodisi piščal ali citre, naj se tudi glase, če pa razločka nimajo v glasovih, kako bomo umeli, kaj se piska ali citra?',
        8: 'Saj tudi če da trobenta nerazločen glas, kdo se pripravi za boj?',
        9: 'Tako tudi z vami: če z jezikom ne govorite razumljive besede, kako bodo umeli, kaj pravite? V zrak boste govorili.',
        10: 'Toliko raznovrstnih glasov, postavim, je na svetu in nobeden ni brez pomena.',
        11: 'Če torej ne vem pomena glasu, bodem tujec govorečemu in govoreči bode meni tujec.',
        12: 'Tako tudi z vami: ker ste vneti za duhovne dari, iščite, da jih imate obilo in ž njimi služite v napredovanje cerkve.',
        13: 'Zato, kdor govori v jeziku, naj moli, da bi mogel razkladati.',
        14: 'Kajti če molim v jeziku, duh moj moli, a um moj je brez sadu.',
        15: 'Kaj torej? Molil bom z duhom, a molil bom tudi z umom; prepeval bom z duhom, a prepeval bom tudi z umom.',
        16: 'Sicer, če hvališ Boga le z duhom, kako poreče ta, ki je nepoučen, Amen na tvojo zahvalo, ko ne ve, kaj govoriš?',
        17: 'Ti se resda lepo zahvaljuješ, ali drugemu ne služiš za napredek.',
        18: 'Zahvaljujem Boga, da govorim v jezikih bolj nego vi vsi;',
        19: 'toda v cerkvi rečem rajši pet besed s svojim umom, da poučim tudi druge, nego pa deset tisoč besed v jeziku.',
        20: 'Bratje, ne bodite deca v razumu, ampak v zlobi bodite deca, a v razumu bodite popolni!',
        21: 'V postavi je pisano: „S tujimi jeziki in z ustnami tujcev bom govoril temu ljudstvu, in tudi tako me ne bodo poslušali, pravi Gospod“.',
        22: 'Jeziki so torej za znamenje ne tem, ki verujejo, temuč nevernim, proroštvo pa ne nevernim, temuč tem, ki verujejo.',
        23: 'Ko bi se torej sešla cerkev vsa na en kraj in bi vsi govorili jezike in bi prišli tja tudi nepoučeni ali neverniki, ne poreko li, da norite?',
        24: 'Ko pa vsi prorokujejo, a pride tja kak nevernik ali nepoučen človek, ga prepričujejo vsi, ga sodijo vsi,',
        25: 'skrivnosti njegovega srca se razodevajo, in tako bo padel na obraz in molil Boga in priznaval, da je Bog zares med vami.',
        26: 'Kaj torej, bratje? Kadar se shajate, ima vsak vas ali psalm, ali nauk, ali razodetje, ali jezik, ali razkladanje. Vse naj se zgodi tako, da se pospešuje napredek.',
        27: 'Če kdo govori v jeziku, naj govorita po dva ali kvečjemu po trije in drug za drugim, in eden naj razklada.',
        28: 'Ko bi pa ne bilo razkladalca, naj molči v zboru, a govori naj sebi in Bogu.',
        29: 'Proroki naj pa govore dva ali trije, drugi naj pa razsojajo.',
        30: 'Ako pa drugi, ki sedi zraven, prejme razodetje, naj molči prvi.',
        31: 'Kajti morete vsi, eden po eden, prorokovati, da prejmo vsi pouk in se vsi potolažijo.',
        32: 'In duhovi proroški so pokorni prorokom;',
        33: 'zakaj Bog ni Bog nereda, ampak miru, kakor po vseh zborih svetniških.',
        34: 'Žene naj v vaših zborih molče; kajti ni jim dopuščeno govoriti, temuč podložne naj bodo, kakor veli tudi postava.',
        35: 'A če se hočejo česa naučiti, doma naj vprašajo svoje može; zakaj nespodobno je ženi govoriti v cerkvenem zboru.',
        36: 'Ali pa je od vas izšla beseda Božja? ali pa je prišla k vam samim?',
        37: 'Če kdo misli, da je prorok ali z Duhom obdarovan, naj spozna, kar vam pišem, da je Gospodova zapoved.',
        38: 'Če pa kdo noče umeti, naj ne ume.',
        39: 'Zatorej, bratje moji, gorite za to, da prorokujete, in nikar ne branite govoriti v jezikih!',
        40: 'Vse naj se spodobno in po redu godi.',
    },
    15: {
        1: 'Spominjam vas pa, bratje, evangelija, ki sem vam ga oznanil, ki ste ga tudi sprejeli, ki v njem tudi stojite,',
        2: 'ki se po njem tudi zveličujete, ako hranite besedo, kakor sem vam jo oznanil, če le niste zaman verovali.',
        3: 'Izročil sem vam namreč najprej to, kar sem tudi prejel:',
        4: 'da je Kristus umrl za naše grehe po pismih, in da je bil pokopan in da je bil tretji dan obujen po pismih,',
        5: 'in da se je prikazal Kefu, potem dvanajsterim.',
        6: 'Potem se je prikazal nad petsto bratom naenkrat, katerih večina še sedaj živi, nekaj jih je pa že pozaspalo.',
        7: 'Potem se je prikazal Jakobu, potem vsem apostolom.',
        8: 'In izmed vseh najnazadnje, kakor kakemu negodno rojenemu, se je prikazal tudi meni.',
        9: 'Kajti jaz sem najmanjši izmed apostolov, ki nisem vreden imenovan biti apostol, ker sem preganjal cerkev Božjo;',
        10: 'ali po milosti Božji sem, kar sem, in njegova milost, ki mi jo je podelil, ni bila brezuspešna, marveč deloval sem bolj od njih vseh, toda ne jaz, ampak milost Božja, ki je z menoj.',
        11: 'Bodisi torej jaz ali oni, tako oznanjujemo in tako ste sprejeli vero.',
        12: 'Če se pa oznanjuje, da je Kristus iz mrtvih vstal, kako pravijo nekateri med vami, da ni vstajenja mrtvih?',
        13: 'Če pa ni vstajenja mrtvih, tudi Kristus ni vstal.',
        14: 'A če Kristus ni vstal, prazno je potem naše oznanjevanje, prazna pa tudi vera vaša.',
        15: 'Kažemo se pa tudi lažnive priče Božje, ker smo popričali zoper Boga, da je obudil Kristusa, ki ga pa ni obudil, če mrtvi ne vstajajo.',
        16: 'Kajti če mrtvi ne vstajajo, tudi Kristus ni vstal.',
        17: 'A če Kristus ni vstal, ničeva je vera vaša, še ste v grehih svojih.',
        18: 'Potemtakem so tudi ti, ki so v Kristusu zaspali, izgubljeni.',
        19: 'Če upamo v Kristusa samo v tem življenju, smo vredni pomilovanja najbolj izmed vseh ljudi.',
        20: 'Res pa je Kristus vstal iz mrtvih, prvina tistih, ki so pozaspali.',
        21: 'Zakaj ker je po človeku prišla smrt, je po človeku prišlo tudi vstajenje mrtvih.',
        22: 'Kakor namreč v Adamu vsi mrjo, tako bodo tudi v Kristusu vsi oživeli.',
        23: 'Ali vsak v svojem redu: prvina Kristus; potem ti, kateri so Kristusovi, ob prihodu njegovem;',
        24: 'potem pride konec, kadar on izroči kraljestvo Bogu in Očetu, kadar odpravi vsako poglavarstvo in vsako oblast in moč.',
        25: 'Kajti on mora kraljevati dotlej, dokler Bog ne dene vseh sovražnikov pod njegove noge.',
        26: 'A najzadnji sovražnik, ki se odpravi, je smrt.',
        27: 'Vse je namreč položil pod njegove noge. Toda ko pravi: „Vse je podloženo“, je očitno, da vse razen tega, ki mu je vse podložil.',
        28: 'Kadar se pa vse njemu podloži, tedaj se tudi sam Sin podloži temu, ki mu je vse podložil, da bi Bog bil vse v vsem.',
        29: 'Sicer pa kaj bodo počeli, kateri se krščujejo za mrtve? Če sploh mrtvi ne vstajajo, kaj se še krščujejo zanje?',
        30: 'Zakaj se tudi mi nevarnostim izpostavljamo vsako uro?',
        31: 'Pričam pri hvali zastran vas, bratje, ki jo imam v Kristusu Jezusu, Gospodu našem: vsak dan umiram.',
        32: 'Če sem se po človeško boril z zvermi v Efezu, kakšno imam korist? Če mrtvi ne vstajajo, „jejmo in pijmo, kajti jutri umremo!“',
        33: 'Ne dajte se zavesti! Dobre navade pačijo slabi pogovori.',
        34: 'Predramite se pravično in ne grešite! kajti spoznanja Božjega nekateri nimajo, na sramoto vam to pravim.',
        35: 'Toda poreče kdo: Kako vstajajo mrtvi? in v kakšnem telesu prihajajo?',
        36: 'Nespametnež, kar ti seješ, ne oživi, če ni prej umrlo.',
        37: 'In kar seješ, ne seješ telesa, katero ima biti, temuč golo zrno, postavim, pšenično ali katero drugo;',
        38: 'a Bog mu daje telo, kakor hoče, in vsakemu semenu lastno mu telo.',
        39: 'Ni vse meso enako meso, temuč drugo je meso človečje, drugo meso živinsko, drugo ptičje in drugo ribje.',
        40: 'So tudi telesa nebeška in telesa zemeljska, toda druga je slava nebeških, a druga zemeljskih.',
        41: 'Druga je slava solnca in druga slava meseca in druga slava zvezd, kajti zvezda se od zvezde loči v slavi.',
        42: 'Tako tudi je vstajenje mrtvih. Seje se v trohljivosti, vstaja v netrohljivosti;',
        43: 'seje se v nečasti, vstaja v slavi; seje se v slabosti, vstaja v moči;',
        44: 'seje se telo naravno, vstaja telo duhovno. Če je naravno telo, je tudi duhovno telo.',
        45: 'Tako je tudi pisano: „Postal je prvi človek Adam duša živa“. Zadnji Adam je postal duh oživljajoč.',
        46: 'Ali ni prvo duhovno, ampak naravno, potem duhovno.',
        47: 'Prvi človek je iz zemlje, prstén, drugi človek je iz nebes.',
        48: 'Kakršen je prsteni, taki so prsteni, in kakršen nebeški, taki so nebeški.',
        49: 'In kakor smo nosili podobo prstenega, nosili bomo tudi podobo nebeškega.',
        50: 'To pa pravim, bratje, da meso in kri ne moreta podedovati Božjega kraljestva, tudi trohljivost ne deduje netrohljivosti.',
        51: 'Glejte, skrivnost vam govorim: Vsi ne zaspimo, a vsi se izpremenimo',
        52: 'v hipu, v trenutku, ob poslednji trobenti; kajti trobenta zatrobi in mrtvi vstanejo netrohljivi, in mi se izpremenimo.',
        53: 'To trohljivo mora namreč obleči netrohljivost in to smrtno obleči nesmrtnost.',
        54: 'Kadar pa to trohljivo obleče netrohljivost in to smrtno obleče nesmrtnost, tedaj se zgodi tista beseda, ki je napisana: „Požrta je smrt v zmagi“.',
        55: 'Kje je, smrt, tvoja zmaga? Kje je, smrt, tvoje želo?',
        56: 'Želo smrti pa je greh, a moč greha je postava.',
        57: 'Ali hvala Bogu, ki nam daje zmago po Gospodu našem Jezusu Kristusu.',
        58: 'Zato, bratje moji ljubljeni, bodite stanovitni, nepremični, obilni vsekdar v delu Gospodovem, vedoč, da vaš trud ni prazen v Gospodu.',
    },
    16: {
        1: 'A glede sklada za svete storite tudi vi tako, kakor sem naredil za galacijske cerkve.',
        2: 'Prvi dan po soboti naj vsak vas pri sebi deva na stran in spravlja po svojih dohodkih, da ne bode zbiranja šele takrat, kadar pridem.',
        3: 'Kadar pa pridem, pošljem z listi tiste, ki jih za dobre za to spoznate, da odneso vaš dar ljubezni v Jeruzalem;',
        4: 'ko bi pa vredno bilo, da tudi jaz grem, pojdejo z menoj.',
        5: 'Pridem pa k vam, kadar prepotujem Macedonijo; pojdem namreč skozi Macedonijo;',
        6: 'a pri vas se morebiti pomudim ali pa ostanem tudi čez zimo, da me vi spremite, kamor koli pojdem.',
        7: 'Kajti nočem vas le mimogrede videti, marveč upam, da ostanem nekoliko časa pri vas, če Gospod dovoli.',
        8: 'Ostanem pa v Efezu do Binkošti.',
        9: 'Zakaj vrata so mi odprta velika in široka in nasprotnikov je mnogo.',
        10: 'Ako pa pride Timotej, glejte, da bode brez strahu pri vas; kajti opravlja Gospodovo delo kakor i jaz:',
        11: 'nihče naj ga torej ne zaničuje. A odpošljite ga v miru, da pride k meni, ker ga pričakujem z brati.',
        12: 'Kar se pa tiče Apola brata, dosti sem ga prosil, da bi šel k vam z brati; a nikakor ga ni bila volja iti sedaj, toda pride, kadar utegne.',
        13: 'Čujte, stojte v veri, moški se držite, trdni bodite!',
        14: 'Vse vaše naj se godi v ljubezni.',
        15: 'Prosim pa vas, bratje: za Štefanov dom veste, da je prvina v Ahaji in da so se za službo svetim odločili;',
        16: 'da bodite tudi vi podložni takim in vsakemu, ki pomaga v delu in se trudi.',
        17: 'Veselim se pa prihoda Štefanovega in Fortunatovega in Ahaikovega, ker so mi nadomestili, kar sem na vas pogrešal;',
        18: 'zakaj poživili so mojega duha in vašega. Spoštujte torej take!',
        19: 'Pozdravljajo vas cerkve v Aziji. Pozdravljata vas v Gospodu mnogokrat Akvila in Priska s cerkvijo, ki se shaja v njunem domu.',
        20: 'Pozdravljajo vas bratje vsi. Pozdravite drug drugega v svetem poljubu!',
        21: 'Pozdrav z mojo, Pavlovo, roko.',
        22: 'Če kdo ne ljubi Gospoda, proklet bodi! Maran atha.',
        23: 'Milost Gospoda Jezusa z vami!',
        24: 'Moja ljubezen z vami vsemi v Kristusu Jezusu! Amen.',
    },
}
